<?php
require __DIR__.'/../inc/bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if($action==='read'){$db->prepare('UPDATE contact_messages SET is_read=1 WHERE id=?')->execute([$id]);flash('success','Message marked as read.');}elseif($action==='delete'){$db->prepare('DELETE FROM contact_messages WHERE id=?')->execute([$id]);flash('success','Message deleted.');}redirect('gadmin8f3k2p9x7m4q6v1c/contacts.php');}
$messages=$db->query('SELECT * FROM contact_messages ORDER BY is_read ASC,created_at DESC')->fetchAll();$adminTitle='Contact Messages';require __DIR__.'/_header.php';
?>
<section class="panel"><h2>Website inquiries</h2><?php if(!$messages):?><div class="empty">No contact messages yet.</div><?php else:?><?php foreach($messages as $m):?><article style="padding:18px 0;border-bottom:1px solid var(--line);<?=!$m['is_read']?'background:#f8fbfc':''?>"><div class="panel-head"><div><strong><?=h($m['name'])?></strong> <?php if(!$m['is_read']):?><span class="badge">New</span><?php endif;?><br><a href="mailto:<?=h($m['email'])?>"><?=h($m['email'])?></a><?= $m['phone']?' · '.h($m['phone']):''?><div class="meta"><?=h(date('F j, Y · g:i A',strtotime($m['created_at'])))?></div></div><div class="actions"><?php if(!$m['is_read']):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="read"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="btn btn-secondary btn-small">Mark read</button></form><?php endif;?><form method="post" onsubmit="return confirm('Delete this message?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="btn btn-danger btn-small">Delete</button></form></div></div><p><?=nl2br(h($m['message']))?></p></article><?php endforeach;?><?php endif;?></section>
<?php require __DIR__.'/_footer.php';?>
